<svelte:options runes={true} />

<script lang="ts">
  // Roadmap overview and project progress.
  import RoadmapActivity from '../../../lib/components/RoadmapActivity.svelte';
  import RoadmapLiveWork from '../../../lib/components/RoadmapLiveWork.svelte';
  import { formatDate, projectInitials } from '../../../lib/state';
  import NavIcon from '../../../lib/components/NavIcon.svelte';
  import { openWorkTask } from '../../drawer/open';
  import { enterExplore } from '../../explore';
  import { analyzeProjectIntelligence, cancelProjectIntelligence, projectAttentionLabel } from '../../projects';
  import { loadRoadmap, openRoadmapActivity, openRoadmapTask } from '../../roadmap';
  import { selectProject, setView } from '../../routing';
  import { explore } from '../../state/explore.svelte';
  import { live } from '../../state/live.svelte';
  import { roadmapData } from '../../state/roadmapData.svelte';
  import { workspace } from '../../state/workspace.svelte';
  import { taskDueClass } from '../../taskQueries';
  import RoadmapExploreBar from './RoadmapExploreBar.svelte';

  // Labels follow the summary's scope; zero tasks is "no tasks", not 0% progress.
  const scoped = $derived(Boolean(roadmapData.roadmapProject));
  const empty = $derived(roadmapData.roadmapTotal === 0);
</script>

{#if explore.active}<RoadmapExploreBar title={roadmapData.roadmapProject ? `${roadmapData.roadmapProject.name} progress` : 'Roadmap overview'} />{:else}<section class="page-heading"><div><div class="breadcrumbs"><span>Workspace</span><span>/</span><span>{roadmapData.roadmapProject ? roadmapData.roadmapProject.key : 'Overview'}</span></div><h1>{roadmapData.roadmapProject ? `${roadmapData.roadmapProject.name} progress` : 'Roadmap overview'}</h1><p>{roadmapData.roadmapProject ? 'Task state, deadlines and recent activity for this project.' : 'A high-level pulse on every project and what needs attention next.'}</p></div><div class="heading-actions"><button bind:this={explore.trigger} class="button quiet-button" type="button" aria-label="Explore roadmap" title="Hide everything else and enlarge the roadmap" on:click={() => void enterExplore()}><NavIcon name="expand" />Explore</button>{#if roadmapData.roadmapProject}<button class="button quiet-button" type="button" on:click={() => setView('roadmap')}>All projects</button>{:else if workspace.projectIntelligenceAnalyzing}<button class="button quiet-button" type="button" on:click={cancelProjectIntelligence}>Cancel Luna</button>{:else}<button class="button primary" type="button" on:click={analyzeProjectIntelligence}>Analyze with Luna</button>{/if}<button class="button quiet-button" type="button" on:click={() => loadRoadmap(roadmapData.roadmapProjectId)}>↻ Refresh</button></div></section>{/if}
{#if roadmapData.roadmapError}<div class="inline-alert error content-alert" role="alert" data-roadmap-unavailable><span>!</span><span>Progress figures are unavailable. {roadmapData.roadmapError}</span><button class="text-button" type="button" on:click={() => loadRoadmap(roadmapData.roadmapProjectId)}>Retry</button></div>{/if}
{#if roadmapData.roadmapLoading}<div class="roadmap-skeleton"><div></div><div></div><div></div></div>{:else if roadmapData.roadmapSummaryCurrent}<section class="roadmap-content"><div class="roadmap-hero"><div class="hero-copy"><span class="eyebrow">{scoped ? 'Project pulse' : 'Workspace pulse'}</span><h2>Momentum, at a glance.</h2><p>{scoped ? "Progress is calculated from this project's task states." : 'Progress is calculated from the task states of projects you can access.'}</p></div><div class="hero-progress"><div class="progress-ring" style={`--progress: ${roadmapData.roadmapCompletion}%`}><span>{#if empty}—{:else}{Math.round(roadmapData.roadmapCompletion)}<small>%</small>{/if}</span></div><div>{#if empty}<strong>No tasks yet</strong><span>Completion appears once tasks exist.</span>{:else}<strong>{roadmapData.roadmapTotal} total tasks</strong><span>{roadmapData.roadmapCompleted} marked complete</span>{/if}</div></div></div><div class="metric-grid"><div class="metric-card"><span class="metric-icon purple">◒</span><span class="metric-label">Completion</span><strong>{empty ? '—' : `${Math.round(roadmapData.roadmapCompletion)}%`}</strong><span class="metric-note">{empty ? 'No tasks yet' : scoped ? 'In this project' : 'Across your projects'}</span></div><div class="metric-card"><span class="metric-icon red">!</span><span class="metric-label">Overdue</span><strong>{roadmapData.roadmap?.overdue_count ?? 0}</strong><span class="metric-note">Need attention</span></div><div class="metric-card"><span class="metric-icon amber">◷</span><span class="metric-label">Due soon</span><strong>{roadmapData.roadmap?.due_soon_count ?? 0}</strong><span class="metric-note">Next 7 days</span></div><div class="metric-card"><span class="metric-icon green">✓</span><span class="metric-label">Tasks marked complete</span><strong>{roadmapData.roadmapCompleted}</strong><span class="metric-note">Board state, not deployment</span></div></div>{#if !roadmapData.roadmapProject}<section class="project-intelligence-panel" aria-labelledby="project-intelligence-heading"><div class="roadmap-panel-heading"><div><h2 id="project-intelligence-heading">Smart project attention</h2><p>{workspace.projectIntelligence?.source === 'luna' ? 'Luna analysis from your last manual run.' : 'Metric-based ordering. Luna runs only when you click Analyze.'}</p></div>{#if workspace.projectIntelligence}<span class={`intelligence-source ${workspace.projectIntelligence.source}`}>{workspace.projectIntelligence.source === 'luna' ? 'Luna' : 'Metrics'}</span>{/if}</div>{#if workspace.projectIntelligenceError}<div class="inline-alert error" role="alert"><span>!</span>{workspace.projectIntelligenceError}</div>{/if}{#if workspace.projectIntelligence?.workspace_insights.length}<div class="intelligence-insights">{#each workspace.projectIntelligence.workspace_insights as insight}<article><span>{insight.kind.replaceAll('_', ' ')}</span><p>{insight.summary}</p></article>{/each}</div>{:else if workspace.projectIntelligenceLoading}<div class="roadmap-live-loading"><span class="spinner"></span>Loading metric snapshot…</div>{:else}<p class="intelligence-empty">No cross-project insight yet. Smart order still uses the deterministic metrics above.</p>{/if}</section>{/if}<RoadmapLiveWork tasks={roadmapData.roadmapLiveTasks} projects={workspace.projects} columnsByProject={roadmapData.roadmapLiveColumnsByProject} actors={roadmapData.roadmapActors} now={live.pulseClock} loading={roadmapData.roadmapLiveLoading} error={roadmapData.roadmapLiveError} onOpen={openRoadmapTask} onViewAll={() => setView('my-work')} /><div class="roadmap-columns"><section class="roadmap-panel project-progress-panel"><div class="panel-heading"><div><h2>Project progress</h2><p>{scoped ? 'Where this project stands today.' : 'Where each project stands today.'}</p></div><button class="icon-button" type="button" aria-label="Refresh progress" on:click={() => loadRoadmap(roadmapData.roadmapProjectId)}>↻</button></div>{#if roadmapData.roadmapProjectRows.length}{#each roadmapData.roadmapProjectRows as row}<button class="project-progress-row" type="button" on:click={() => selectProject(row.project)}><span class="project-dot" style={`--project-color: ${row.project.color || '#6d5efc'}`}>{projectInitials(row.project)}</span><span class="project-progress-name"><strong>{row.project.name}</strong><small>{row.project.key}</small></span>{#if workspace.projectOrderMode === 'smart' && workspace.projectIntelligenceById.get(row.project.id)}<span class={`attention-pill ${workspace.projectIntelligenceById.get(row.project.id)?.attention}`}>{projectAttentionLabel(workspace.projectIntelligenceById.get(row.project.id))}</span>{/if}<span class="progress-track"><span style={`width: ${row.total_tasks ? (row.completed_tasks / row.total_tasks) * 100 : 0}%; --project-color: ${row.project.color || '#6d5efc'}`}></span></span><span class="progress-number">{row.total_tasks ? `${Math.round((row.completed_tasks / row.total_tasks) * 100)}%` : 'No tasks'}</span><span>→</span></button>{/each}{:else}<div class="panel-empty">Create a project to see progress here.</div>{/if}</section><section class="roadmap-panel upcoming-panel"><div class="panel-heading"><div><h2>Coming up</h2><p>Tasks with the nearest due dates.</p></div></div>{#if roadmapData.roadmap?.upcoming_tasks?.length}{#each roadmapData.roadmap.upcoming_tasks.slice(0, 5) as task}<button class="upcoming-row" type="button" on:click={() => openWorkTask(task)}><span class="upcoming-key">{task.key}</span><span class="upcoming-title">{task.title}</span><span class={`upcoming-date ${taskDueClass(task)}`}>{formatDate(task.due_at)}</span></button>{/each}{:else}<div class="panel-empty">No upcoming deadlines. Nice breathing room.</div>{/if}</section></div><RoadmapActivity events={roadmapData.roadmapActivityEvents} tasksById={roadmapData.roadmapActivityTasks} projects={workspace.projects} actors={roadmapData.roadmapActors} filter={roadmapData.roadmapActivityFilter} loading={roadmapData.roadmapActivityLoading} error={roadmapData.roadmapActivityError} onFilterChange={(next) => roadmapData.roadmapActivityFilter = next} onOpen={openRoadmapActivity} /></section>{/if}
